class Vehicle {String vehicleNo,brand;double baseFare;Vehicle(String no,String brand,double fare){vehicleNo=no;this.brand=brand;baseFare=fare;}double calculateFare(int days){return 0;}void displayBill(double amount){System.out.printf("Vehicle No: %s%nBrand: %s%nTotal Fare: %.2f%n---------------------%n",vehicleNo,brand,amount);}}
class Car extends Vehicle {boolean acAvailable;Car(String no,String brand,double fare,int seats,boolean ac){super(no,brand,fare);acAvailable=ac;}double calculateFare(int days){return baseFare*days+(acAvailable?500:0);}}
class Bike extends Vehicle {Bike(String no,String brand,double fare,boolean helmet,boolean geared){super(no,brand,fare);}double calculateFare(int days){return baseFare*days;}}
class SUV extends Vehicle {int luxuryLevel;SUV(String no,String brand,double fare,boolean fwd,int level){super(no,brand,fare);luxuryLevel=level;}double calculateFare(int days){return baseFare*days+luxuryLevel*1000;}}
public class Program7 {public static void main(String[] args){Vehicle[] vehicles={new Car("C101","Hyundai",2000,5,true),new Bike("B101","Honda",500,true,true),new SUV("S101","Toyota",3000,true,2)};for(Vehicle vehicle:vehicles)vehicle.displayBill(vehicle.calculateFare(3));}}
